-- =============================================================================
-- CYBERTUBE: SEED ENGLISH COMMUNICATION FOR CYBERSECURITY ZERO TO ADVANCED
-- =============================================================================
-- Description:
-- Idempotently seeds the 30-module English Communication for Cybersecurity course,
-- all 30 modules, and all 120 lessons into the Supabase database.
-- =============================================================================

DO $$
DECLARE
  v_course_id UUID := 'de000000-0000-4000-8000-000000000001';
BEGIN
  -- 1. Insert/Update Course
  INSERT INTO public.courses (
    id,
    slug,
    title,
    short_description,
    description,
    difficulty,
    estimated_duration,
    total_duration_minutes,
    thumbnail_url,
    instructor_name,
    instructor_title,
    instructor_org,
    status,
    tags,
    prerequisites,
    learning_objectives,
    track,
    domains,
    featured
  ) VALUES (
    v_course_id,
    'english-communication-for-cybersecurity-zero-to-advanced',
    'English Communication for Cybersecurity: Zero to Advanced',
    'Master professional English speaking, listening, technical reporting, shift handovers, and executive stakeholder briefings designed specifically for cybersecurity professionals and SOC analysts.',
    'A comprehensive 30-module, 120-lesson video-first curriculum developing clear pronunciation of technical identifiers, active listening across international accents, concise ticket writing, TLP intelligence reporting, and high-pressure executive communication for SOC analysts, incident responders, and ethical hackers.',
    'beginner',
    '20 weeks (80 hours)',
    4800,
    'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=800&q=80',
    'BBC Learning English & Oxford English',
    'Language & Technical Communications Faculty',
    'CyberTube Academy',
    'published',
    ARRAY['english-communication', 'soc-analyst', 'incident-response', 'soft-skills', 'workplace-communication', 'technical-writing']::TEXT[],
    ARRAY['Basic familiarity with computers, operating systems, and networking concepts', 'Willingness to practice spoken English and pronunciation aloud', 'Web browser with audio/video playback capability']::TEXT[],
    ARRAY['Speak intelligible workplace English and accurately pronounce technical cybersecurity identifiers (IPs, hashes, hostnames)', 'Listen actively to security briefings across international accents and request clarification without ambiguity or speculation', 'Write concise, factually grounded SOC incident triage tickets, escalation emails, and shift handover reports', 'Deliver structured verbal briefings to both deeply technical engineers and non-technical executive stakeholders', 'Excel in cybersecurity technical job interviews using structured STAR communication frameworks']::TEXT[],
    'cybersecurity',
    ARRAY['fundamentals', 'soc-blue-team']::TEXT[],
