  -- 2. Insert/Update 30 Modules (Multi-Row)
  INSERT INTO public.course_modules (id, course_id, title, description, order_index) VALUES
  ('de000000-0000-4000-8000-000000010001', v_course_id, 'Module 01: Module 01 — Sound Foundations for Security Terms', 'Foundation: Speak from Zero stage (A1). Outcome: Say English sounds clearly enough to be understood while reading security identifiers.', 1),
  ('de000000-0000-4000-8000-000000010002', v_course_id, 'Module 02: Module 02 — Alphabet, Digits, IP Addresses and Spelling', 'Foundation: Speak from Zero stage (A1). Outcome: Spell identifiers and read digits, times and addresses without confusing the listener.', 2),
  ('de000000-0000-4000-8000-000000010003', v_course_id, 'Module 03: Module 03 — Greetings, Introductions and SOC Roles', 'Foundation: Speak from Zero stage (A1). Outcome: Introduce yourself and your security-team role politely in a workplace situation.', 3),
  ('de000000-0000-4000-8000-000000010004', v_course_id, 'Module 04: Module 04 — Basic English Sentence Construction', 'Foundation: Speak from Zero stage (A1). Outcome: Write and speak simple subject–verb–object sentences about security events.', 4),
  ('de000000-0000-4000-8000-000000010005', v_course_id, 'Module 05: Module 05 — Questions, Confirmation and Basic Dialogue', 'Foundation: Speak from Zero stage (A1). Outcome: Ask focused questions and confirm answers without embarrassment.', 5),
  ('de000000-0000-4000-8000-000000010006', v_course_id, 'Module 06: Module 06 — Present, Past and Future for Incident Updates', 'Listening and Technical Explanation stage (A1). Outcome: Distinguish what happened, what is happening and what happens next.', 6),
  ('de000000-0000-4000-8000-000000010007', v_course_id, 'Module 07: Module 07 — Listening Fundamentals and Taking Notes', 'Listening and Technical Explanation stage (A1). Outcome: Extract who, what, when, where and next action from spoken English.', 7),
  ('de000000-0000-4000-8000-000000010008', v_course_id, 'Module 08: Module 08 — Listening Across Accents and Speaking Speeds', 'Listening and Technical Explanation stage (A1). Outcome: Understand professional speech at varying speeds and request repetition appropriately.', 8),
  ('de000000-0000-4000-8000-000000010009', v_course_id, 'Module 09: Module 09 — Clear Speech, Pacing and Confidence', 'Listening and Technical Explanation stage (A1). Outcome: Deliver short incident statements at a measured pace with understandable phrasing.', 9),
  ('de000000-0000-4000-8000-000000010010', v_course_id, 'Module 10: Module 10 — Explaining Security Vocabulary in Plain English', 'Listening and Technical Explanation stage (A1). Outcome: Explain common cybersecurity terms to someone with no security background.', 10),
  ('de000000-0000-4000-8000-000000010011', v_course_id, 'Module 11: Module 11 — Describing Devices, Accounts and Networks', 'Workplace Reading and Writing stage (A1). Outcome: Explain where an alert occurred, which account is involved and what systems are affected.', 11),
  ('de000000-0000-4000-8000-000000010012', v_course_id, 'Module 12: Module 12 — Asking for Clarification and Active Listening', 'Workplace Reading and Writing stage (A1). Outcome: Check instructions, restate requests and avoid miscommunication during security work.', 12),
  ('de000000-0000-4000-8000-000000010013', v_course_id, 'Module 13: Module 13 — Reading Security Alerts, Tickets and Instructions', 'Workplace Reading and Writing stage (A1). Outcome: Identify essential facts and uncertainties in a short English-language security ticket.', 13),
  ('de000000-0000-4000-8000-000000010014', v_course_id, 'Module 14: Module 14 — Writing Clear, Concise SOC Notes', 'Workplace Reading and Writing stage (A1). Outcome: Write short, factual and grammatically clear investigation notes.', 14),
  ('de000000-0000-4000-8000-000000010015', v_course_id, 'Module 15: Module 15 — Professional Email for Security Teams', 'Workplace Reading and Writing stage (A1). Outcome: Write clear escalation, follow-up and information-request emails.', 15),
  ('de000000-0000-4000-8000-000000010016', v_course_id, 'Module 16: Module 16 — Professional Chat and Remote Team Messaging', 'SOC Calls, Reports and Escalation stage (A1). Outcome: Use clear, non-alarming language in SOC chat channels and collaborate asynchronously.', 16),
  ('de000000-0000-4000-8000-000000010017', v_course_id, 'Module 17: Module 17 — Telephone, Video Calls and Conference Etiquette', 'SOC Calls, Reports and Escalation stage (A1). Outcome: Lead a short security verification call, handle audio problems and confirm decisions.', 17),
  ('de000000-0000-4000-8000-000000010018', v_course_id, 'Module 18: Module 18 — SOC Shift Handover and Status Briefings', 'SOC Calls, Reports and Escalation stage (A1). Outcome: Deliver a structured and concise handover to the next SOC shift.', 18),
  ('de000000-0000-4000-8000-000000010019', v_course_id, 'Module 19: Module 19 — Chronological Incident Narratives and Timelines', 'SOC Calls, Reports and Escalation stage (A1). Outcome: Build a consistent, evidence-based spoken and written incident timeline.', 19),
  ('de000000-0000-4000-8000-000000010020', v_course_id, 'Module 20: Module 20 — Triage Findings and Escalation English', 'SOC Calls, Reports and Escalation stage (A1). Outcome: Explain why an alert needs review and request appropriate escalation.', 20),
  ('de000000-0000-4000-8000-000000010021', v_course_id, 'Module 21: Module 21 — Phishing Communication and User Interviews', 'SOC Calls, Reports and Escalation stage (A1). Outcome: Interview a potential phishing recipient respectfully and document the facts.', 21),
  ('de000000-0000-4000-8000-000000010022', v_course_id, 'Module 22: Module 22 — Vulnerability, Risk and Recommendation Language', 'SOC Calls, Reports and Escalation stage (A1). Outcome: Explain the difference between a finding, possible impact and remediation advice.', 22),
  ('de000000-0000-4000-8000-000000010023', v_course_id, 'Module 23: Module 23 — Reading and Summarising Threat Intelligence', 'Advanced Team Communication stage (A1). Outcome: Convert a lengthy source into an accurate, short analyst summary.', 23),
  ('de000000-0000-4000-8000-000000010024', v_course_id, 'Module 24: Module 24 — Executive Summaries and Nontechnical Explanations', 'Advanced Team Communication stage (A1). Outcome: Explain technical events and decisions to nontechnical managers.', 24),
  ('de000000-0000-4000-8000-000000010025', v_course_id, 'Module 25: Module 25 — Participating in and Chairing Security Meetings', 'Advanced Team Communication stage (A1). Outcome: Run a short agenda-driven security meeting and record decisions.', 25),
  ('de000000-0000-4000-8000-000000010026', v_course_id, 'Module 26: Module 26 — Disagreement, Feedback and Collaborative Problem-Solving', 'Advanced Team Communication stage (A1). Outcome: Disagree without blame while protecting accuracy and team relationships.', 26),
  ('de000000-0000-4000-8000-000000010027', v_course_id, 'Module 27: Module 27 — Cybersecurity Presentations and Demos in English', 'Advanced Team Communication stage (A1). Outcome: Give a structured technical explanation with signposting and audience questions.', 27),
  ('de000000-0000-4000-8000-000000010028', v_course_id, 'Module 28: Module 28 — Stakeholder Updates and High-Pressure Communication', 'Career and Capstone stage (A1). Outcome: Give calm, timely and uncertainty-aware security status updates.', 28),
  ('de000000-0000-4000-8000-000000010029', v_course_id, 'Module 29: Module 29 — Cybersecurity Job Interviews and Portfolio Storytelling', 'Career and Capstone stage (A1). Outcome: Answer behavioural and technical-communication interview questions fluently.', 29),
  ('de000000-0000-4000-8000-000000010030', v_course_id, 'Module 30: Module 30 — Integrated SOC Communication Capstone', 'Career and Capstone stage (A1). Outcome: Communicate through the full fictional incident lifecycle with evidence-based, audience-specific English.', 30)
